INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (1, '20251126', 'November 26, 2025 - Robson', 'Devlog #1: Font Fiasco', 'Too Add', 'Welcome to our first devlog, I hope you enjoy the chaos and fun! our Unity editor decided to have a complete temper tantrum this week.', 'Too Add', 'Every time we so much as hovered a mouse over a button, the console exploded with errors. <br><br>Turns out, it wasn''t our ''spaghetti code'' for once. It was a font. A font.<br><br><strong>The Problem:</strong> The Unity editor UI was in a mood every time we hovered over... well, anything hoverable. It was less ''game development'' and more ''staring at a red wall of error logs and crying'' while trying to keep our focus.<br><br><strong>The Culprit:</strong> From what we can piece together through our tears, Unity swapped its default editor font to Inter but forgot to tell, you know, the actual editor. The resulting incompatibility meant the UI didn''t know how to talk to itself anymore.<br><br><strong>The Fix (or: How we saved our brain power):</strong> Thankfully we didn''t need a complex refactor or a 3:00 AM emergency patch. We just needed to point Unity back in the right direction.<br><br><strong>The Solution:</strong> Headed into Edit → Preferences → General and swapped the editor font from Inter (Default) to System Font.<br><br><strong>The Result:</strong> Total silence. The errors vanished, the UI is behaving, and we can finally go back to making magic instead of fighting the software.<br><br>We’re back in the zone now. Time for another round of ramen and some actual progress. Stay caffeinated out there. ✌️✨', 'Too Add', '');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (2, '20251201', 'December 1, 2025 - Robson', 'Devlog: Ghosts, Gravity, and Ground Checks...Oh my! 👻', 'Too Add', 'We ran into a bug so bizarre it felt like our project was actually possessed.', 'Too Add', 'Whenever we hit ''restart'' in the Unity editor, the whole prototype would just... give up. Keys became un-grabbable, animations froze mid-frame, and the console turned into a graveyard of sound-related errors. Strangely, the itch.io build worked perfectly, making this a classic case of ''well it works on my machine (but only sometimes).''<br><br><strong>The Theory:</strong> While we’re still not 100% sure what gremlin moved in, it looks like our sound manager hit a snag that acted like a digital roadblock. It was killing the update functions across our scripts, stopping everything in its tracks the moment a sound tried to trigger.<br><br><strong>The ''Fix'':</strong> We took a mental break from it and just... stepped away to work on other things. After a month of ignoring it, we came back to find the bug had vanished into thin air. We aren''t questioning the miracle; we''re just glad the restart button isn''t a ''destroy game'' button anymore.<br><br><strong>Defying Gravity!</strong> 🏃💨<br><br>We finally gave our protagonist some verticality. Movement feels a lot less grounded (literally) now that we’ve implemented jumping.<br><br><strong>How it’s built:</strong> We attached a dedicated ''Ground Check'' object to the player. It’s constantly sniffing around for anything tagged with the Ground layer.<br><br><strong>The Logic:</strong> If that check overlaps with the floor, you''re ''grounded.'' Hit the Spacebar, and we punch a hole in physics by overriding the Rigidbody’s Y-velocity to send you skyward. It’s simple, snappy, and feels way better than walking everywhere.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExMmRmcjRsZXRubXlsMTBmcnlxdXJ3NmVhMGM3OThrdHc2Y252ZThyNiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/l1J9z5SmyhtdybtaU/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (3, '20251203', 'December 3, 2025 - Robson', 'Devlog: Out with the old, in with the clean', 'Too Add', 'We finally sat down and performed some much-needed TLC on our audio systems.', 'Too Add', 'The old sound manager was... well, let’s just say it had a personality we didn''t always appreciate. It was confusing, prone to tantrums, and required us to update things in two places at once just to get a single ''thud'' to play.<br><br><strong>The Upgrade:</strong><br><br>Robson channeled some leveled-up coding skills to rewrite the whole thing from scratch. No more jumping between the script and the Unity Inspector like a ADHD squirrel. Now, adding a new audio category is as easy as clicking a single button in the editor.<br><br><strong>The ''Magic'' Behind the Curtain</strong> ✨<br><br>We did a massive deep-clean of the codebase. We ripped out weird, ancient artifacts like #if UNITY_EDITOR blocks that nobody actually understood and were likely the culprits behind our previous ''haunted'' bugs.<br><br>To make the sound dictionary actually look like a human-readable list in the inspector (instead of a digital mess), we utilized some serialized field wizardry:<br><br>By nesting specific classes (list items) within that serialized field, we’ve created a custom interface that lets us manage our audio clips without wanting to pull our hair out. It’s cleaner, it’s faster, and most importantly, it actually makes sense.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExM3FkNzFpbWZsd3l5YWxpb25yMHJ6eTFvcGo5d2hpeDZ1bm00dDN0MyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/MC6eSuC3yypCU/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (5, '20260111', 'January 11, 2026 - Robson', 'Devlog: Small Statures and Sticky Situations', 'Too Add', 'We’ve officially added a crouch mechanic. Cause sometimes you just need to keep a low profile, whether it’s to sneak past a threat or squeeze into a tight spot...', 'Too Add', '<strong>Art of keeping a Low-Profile</strong> 👣<br><br>We’ve officially added a crouch mechanic. Cause sometimes you just need to keep a low profile, whether it’s to sneak past a threat or squeeze into a tight spot we definitely didn''t design as a spot to hide in.<br><br><strong>The Mechanics:</strong> Tapping Left Shift now shrinks the player’s scale from (2, 2, 2) down to (1, 1, 1). This effectively halves your physical presence and hitbox. You move a bit slower, but you can finally fit under those low-hanging obstacles.<br><br><strong>Technical Hiccup:</strong> You can''t just tell a Capsule Collider to be tiny; it has a minimum height based on its radius. We had to perform some collider surgery to make sure the hitbox actually contracted along with the player''s model.<br><br><strong>Grounded</strong> 🚫<br><br><strong>The Bug:</strong> The player character suddenly decided that gravity was a one way street and refused to jump whenever Spacebar was mashed.<br><br><strong>The Culprit:</strong> Our Ground Check object was being a bit too pessimistic. It was positioned slightly too low, missing the floor entirely and leaving the player thinking they were perpetually mid-air.<br><br><strong>The Fix:</strong> A quick re-calibration of the check''s vertical offset. Now it detects the floor properly, and the jump is back in action.<br><br><strong>Your Friendly Neighborhood ''Spider-Man''</strong> 🕷️<br><br><strong>The Bug:</strong> We accidentally gave the player superpowers. If you jumped and moved toward a wall, you’d simply stick to it like glue instead of sliding back down.<br><br><strong>The Logic:</strong> Unity''s physics engine was trying to be helpful by applying force to prevent colliders from overlapping. Unfortunately, that friction was overriding gravity itself.<br><br><strong>The Fix:</strong> We swapped in a new Physics Material with near-zero friction. Now, when you hit a wall, you slide down it like a normal human being.<br><br><strong>What’s Simmering:</strong><br><br>We’re currently working on normalizing movement vectors. We noticed that moving diagonally turned the player into a speed demon (thanks, Pythagoras🙄), so we’re rewriting the math to ensure the speed stays consistent no matter which way you''re pointing.', 'Too Add', '');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (6, '20260115', 'January 15, 2026 - Robson', 'Devlog: Nerfing Pythagoras 📐', 'Too Add', 'We realized our protagonist was accidentally breaking the sound barrier whenever they moved diagonally. If you held down ''W'' and ''D'' simultaneously...', 'Too Add', '<strong>''Speedrunner'' Glitch</strong> (Resolved)<br><br>We realized our protagonist was accidentally breaking the sound barrier whenever they moved diagonally. If you held down ''W'' and ''D'' simultaneously, you’d zoom across the map way faster than if you just walked straight.<br><br><strong>The Cause:</strong> It''s the classic Hypotenuse Headache. When you combine vertical and horizontal input, the engine treats them like the sides of a right-angled triangle. Without any correction, the resulting diagonal path (the hypotenuse) has a greater magnitude than either individual side. Essentially, the player was getting a 1.41x speed boost just for being efficient.<br><br><strong>The Fix:</strong> We implemented Vector Normalization. Now, regardless of how many keys you''re mashing, the direction vector is scaled back to a magnitude of 1 before we apply our movement speed. The math is finally balanced, and the ''diagonal cheat code'' is officially decommissioned.<br><br><strong>Status Report:</strong> 📊<br><br>The movement feels tight, consistent, and (most importantly) intentional. No more accidental super-speed. 😮‍💨', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExbGk1ajA4Nmt2cTVremNpd21reWRvdm11ZmRobDQ0ODZpbmdqbGowdCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/AtX0tb8WIJdvL1BWje/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (7, '20260221', 'February 21, 2026 - Robson', 'Devlog: Parkour, Productivity, and Punching Things 🥊☕', 'Too Add', 'A collection of updates: building a parkour stress test, organizing our task list, adding a basic attack mechanic, and implementing player acceleration.', 'Too Add', 'The ''Stress Test'' Playground<br><br><strong>16/01/2026</strong><br><br>We needed a place to really break the movement physics, so we built a Movement Parkour Course. It’s not pretty, just a chaotic collection of slanted cubes and spheres, but it’s the perfect gauntlet for testing our new jumps and crouches. If we can navigate this mess, we can navigate anything.<br><br><strong>The War Room: Task Edition</strong> <br><br><em>02/02/2026</em><br><br>To keep our brain power focused, we’ve implemented a Developer Task List. It’s a massive backlog of everything we need to achieve to make this game a reality.<br><br><strong>The System:</strong> Total autonomy. Each dev picks a signature color (like a bold orange) and claims a task by tagging it. It keeps the vibes strong, work on what you love, just make sure the job gets done. <br><br><strong>Throwing Hands (The Basic Attack)</strong> 🤼<br><br><em>11/02/2026</em><br><br>We’ve added the first iteration of combat and a base ''Toy'' to act as our punching bag.<br><br><strong>How it works:</strong> Tapping ''K'' triggers an OverlapSphere. It checks a radius defined by our attackSphere object (which we kept visible for dev-testing). If it detects a collider tagged as a ''Toy,'' it calls the TakeDamage() function on that specific object. Simple, effective, and satisfying.<br><br><strong>The Physics of Momentum: Acceleration</strong> ᯓ🏃🏻‍♀️‍➡️<br><br><em>21/02/2026</em><br><br>After a week-long wrestling match with the code (and a lot of console errors on the 13th), we’ve finally added Player Acceleration and Deceleration.<br><br><strong>The Feel:</strong> No more instant-on, instant-off movement. The player now ramps up to top speed and coasts to a stop based on a dedicated acceleration variable.<br><br><strong>The Math:</strong> We’re calculating the speed increment every frame based on the current framerate to keep it smooth. To prevent any weird ''infinite sliding'' glitches, the movement cuts off entirely once the speed drops below a tiny, unnoticeable threshold. It feels way more ''human'' and way less like a sliding block of ice.<br><br><strong>What’s Next:</strong><br><br>We’re refining the ''weight'' of the movement now that we have actual momentum to play with.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPWVjZjA1ZTQ3dHNzNWQ2eDJzOTR2eXIybGRmMjF1bmJiNmRmMnBweHg3Y3FndHFkNSZlcD12MV9naWZzX3NlYXJjaCZjdD1n/191jZlhIeYm3RMXiQx/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (8, '20260222', 'February 22, 2026 - Robson', 'Devlog: Leaner Code, Smarter Squats 🏋️‍♂️✨', 'Too Add', 'We spent today trimming the fat. Our movement logic was getting a bit bloated, so we took a scalpel to the project.', 'Too Add', '<strong>Refining the Foundation</strong><br><br>We spent today trimming the fat. Our movement logic was getting a bit bloated, so we took a scalpel to the project.<br><br><strong>Acceleration Cleanup:</strong> The original movement script was a wall of if statements and redundant variables. Big shoutout to Liam for the assist, we managed to gut the unnecessary bits, making the logic significantly cleaner and easier to maintain without losing that ''human'' momentum feel.<br><br><strong>The Scale Reset:</strong> For some reason, the player was set to a scale of (2, 2, 2), which meant we were constantly calculating everything at double-size for no good reason. We halved the PPU (Pixels Per Unit) and reset the scale to a much more logical (1, 1, 1). It’s the same visual size, but the math is finally sane.<br><br><strong><em>Gravity & ''The Big Leap''</em></strong><br><br>Jumping isn''t just a flat upward force anymore; it’s starting to feel like actual physics.<br><br><strong>Weighted Falling:</strong> We tweaked the gravity curve. The player now accelerates slightly faster when falling than when rising. It gives the jump a ''snappy'' peak and a satisfying, heavy landing.<br><br><strong>Variable Jump Height:</strong> You’re no longer locked into one height. Hold the jump button longer for a high leap, or tap it for a quick hop.<br><br><strong>The Evolution of Crouching</strong> 🧘<br><br><strong>''Hover'' Bug (Resolved):</strong> We noticed that when the player crouched, they’d briefly float in mid-air. Since the pivot point stayed put while the scale shrank, the feet lost contact with the floor. It technically ''fixed itself'' through some physics quirks, but we wanted something more elegant.<br><br><strong>''Smart Crouch'' Transition:</strong><br><br>Instead of an instant, jarring snap to a smaller size, we added a smooth transition. We’re now calculating the scale increment every frame:<br><br>(standingHeight - crouchHeight) / (crouchTransitionSpeed / Time.deltaTime)<br><br>This creates a fluid motion that masks any minor floating and feels much more premium.<br><br><strong>What’s Simmering:</strong><br><br>We’re currently wrestling with Uncrouch Checking. We need to make sure the player can''t stand up if there''s a low ceiling above them.<br><br><strong>The Struggle:</strong> SphereCast was being temperamental, and Raycast kept letting the player’s head clip through the geometry like a ghost. I had to call it a day before I started throwing my keyboard, but we’ll find the right collision logic soon.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExamx3a3NhdjByZ2h5MWU2MzE0YjRxMWY5cW9rNWQ2aHR6OGMwZjd2biZlcD12MV9naWZzX3NlYXJjaCZjdD1n/NGTuqdTwQm7L5nPzWG/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (9, '20260223', 'February 23, 2026 - Robson', 'Devlog: The Ceiling Check & ''Smart'' Standing', 'Too Add', 'We’ve officially conquered the ''head-stuck-in-the-ceiling'' problem. After yesterday’s wrestling match with raycasts and spherecasts...', 'Too Add', '<strong>Mind the Gap (Uncrouch Checking)</strong> 🧠<br><br>We’ve officially conquered the ''head-stuck-in-the-ceiling'' problem. After yesterday’s wrestling match with raycasts and spherecasts, we finally landed on the perfect solution for our Smart Crouching system.<br><br><strong>The Mechanism:</strong> We’ve implemented a Capsule Check that triggers the moment we release the crouch button. It scans the space directly above the player''s head for any physical obstructions. If the ceiling is too low, we stay tucked in our crouch until there''s actually room to stand up.<br><br><strong>Optimization:</strong> To keep our console clean and our performance tight, the uncrouch checker remains completely inactive while we''re standing. No sense in checking for a ceiling if we’re already at full height, it saves us from unnecessary errors and keeps our ''brain power'' focused on the gameplay.<br><br><strong>Status Update:</strong><br><br>The movement suite is feeling incredibly polished now. From the smooth transition of the crouch to the safety of the ceiling check, navigating tight spaces feels like a deliberate, tactical choice rather than a physics gamble.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExcjhibmRybTR1amNhbWJ3dGR5anhnN2oyenRrbGFtN2NldmpkYjY4cCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/L0YxUosFg4JCDeOKRm/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (10, '20260224', 'February 24, 2026 - Robson', 'Devlog: Better Vision, Dead Zones, and Grounded Squats 🎥✨', 'Too Add', 'We pulled the camera in for a tighter angle, added an FOV slider, implemented camera dead zones, and finally fixed that weird floating crouch bug.', 'Too Add', '<strong>A Brighter Perspective</strong> 🔦👌🔥<br><br>We realized our setup was making the game look like a B horror movie, and not the intentional kind. The camera was stuck miles away, and the lighting was anchored to the lens, leaving everything behind the protagonist in a pitch-black void.<br><br><strong>The Adjustment:</strong> We pulled the camera in for a tighter, more engaging angle and moved the primary light source to center on the player. Now we can actually see our surroundings without squinting. 🤓<br><br><strong>Signs of Life</strong><br><br>We’ve added Signs to the world! This is just for funsies for the devs.<br><br><strong>Seeing More (FOV Slider)</strong> ↔️<br><br>We added a Field of View (FOV) slider to the settings.<br><br>How it works: It’s a simple but effective listener. When the player drags the slider, it fires off a function that instantly updates the camera’s FOV value. Whether you want a narrow focus or a fish-eye view of the chaos, the choice is yours.<br><br><strong>Physics & Polish</strong> 🛠️<br><br><strong>''Floating Crouch'' Fix:</strong> We noticed the player could crouch mid-air, which looked... let''s say, physics-defying in the worst way. We’ve now restricted crouching so it only triggers when we’re firmly grounded.<br><br><strong>Smoothing the Ride:</strong> 🏇 We switched the Rigidbody''s interpolation mode to Interpolate to kill that annoying movement jitter. We also bumped the Linear Damping to 1; this makes gravity feel a bit less punishing and keeps the player from dropping like a lead weight.<br><br><strong>Entering the Dead Zone</strong> 🚧😵🚧<br><br>We’ve implemented Camera Dead Zones using Unity’s Cinemachine Position Composer.<br><br><strong>The Feel:</strong> This allows the player to move slightly within a defined center area without the camera immediately jerking to follow. It makes the world feel much more stable and less ''nauseating'' during small, twitchy movements.<br><br><strong>Status Update:</strong><br><br>The game is looking cleaner and feeling steadier with every tweak. We’re finally moving out of the ''jittery prototype'' phase and into something that feels like a real experience.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExc2ZobXdkdzJzMm1hY2ZzaWRnajZ4N2JsZ2t0dnJnc2t1Zmo4dWlxbCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/4SXW1rU9loG1HIXXg2/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (11, '20260312', 'March 12, 2026 - Robson', 'Devlog: The Physics of the Precipice 🧗‍♂️📉', 'Too Add', 'We’ve hit a frustrating snag with how our protagonist handles heights. Right now, if we get even a little too close to a ledge, the player just... slides off.', 'Too Add', '<strong>Edge-Case Nightmare (Unresolved)</strong><br><br>We’ve hit a frustrating snag with how our protagonist handles heights. Right now, if we get even a little too close to a ledge, the player just... slides off. It’s like the floor is made of butter, and once that slide starts, there’s no climbing back up; we’re just stuck fruitlessly ramming into the side of the platform as we descend into the abyss.<br><br><strong>The Culprit:</strong> It’s a classic physics clash. Because we’re using a Capsule Collider, the bottom is naturally curved. The moment the center of gravity shifts past the edge, that curve acts like a slide. Compounding the issue, our movement logic doesn''t have a way to ''grab'' the ledge, so trying to move back just results in us pushing against the vertical face of the wall we''re falling past.<br><br><strong>The Failed Experiments:</strong><br><br><strong>Linear Damping:</strong> We tried cranking this up to see if we could ''stick'' to the edge better, but it just made the entire game feel like we were wading through molasses.<br><br><strong>Box Collider:</strong> We swapped the capsule for a box to get a flat bottom, but it was a total vibe-kill. It made rounding corners feel clunky and jagged, and it completely murdered our momentum every time we landed a jump.<br><br><strong>Current Status:</strong><br><br>We’re leaving this one on the ''Active Headache'' list for now. ¯\_ (ᵕ—ᴗ—)_/¯<br><br>We need to find a way to keep the smooth movement of the capsule without the slippery-slope consequences at the edges. It might be time to look into some custom ledge-detection or a ''friction-fix'' specifically for those perimeter coordinates.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExbTNxdm40N3h6czBmMWZwamczc2J0YWJzdW04NHdueWF0bnRicjQxYiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/3o85xBr4naw8sv7caI/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (12, '20260313', 'March 13, 2026 - Robson', 'Devlog: Standing Our Ground (Ledge Sliding Resolved)', 'Too Add', 'We finally solved the ''slip-and-slide'' nightmare that was haunting our ledges. For a while there, getting too close to a drop-off meant an inevitable, slow descent...', 'Too Add', '<strong>Victory Over the Butter-Edges!</strong> 🏆<br><br>We finally solved the ''slip-and-slide'' nightmare that was haunting our ledges. For a while there, getting too close to a drop-off meant an inevitable, slow descent into the void because of the capsule collider’s rounded base.<br><br><strong>Breakthrough:</strong> We went back to the drawing board with the Box Collider idea. Our initial test with it felt terrible, we were losing all our momentum the second we touched the ground after a jump. We almost gave up on it until Logan pointed out the ''obvious'' detail we’d missed: our capsule had a Physics Material attached to it, but our box collider didn''t.<br><br><strong>The Fix:</strong> We were essentially comparing a ''greased-up'' capsule to a ''high-friction'' box. Once we applied our custom Slip Physics Material to the box collider, everything clicked into place. We now have the flat, stable base of a box)meaning no more sliding off edges, but we kept the slick, snappy momentum we need for our platforming.<br><br><strong>Status Update:</strong><br><br>The movement feels officially ''locked in.'' We can stand right on the edge of a precipice with total confidence, and the jumps feel as fluid as they ever did. It’s a huge weight off our shoulders (and our protagonist''s feet).', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExOGtjbG5nenNxOTNoeDV6amU3dTRzY3pvdm10cDB4eXZtMTc2NncwaCZlcD12MV9naWZzX3NlYXJjaCZjdD1n/3kD720zFVu22rfIA0s/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (13, '20260419', 'April 19, 2026 - Robson', 'Devlog: Visual Clarity & Aerodynamics ✈️💨', 'Too Add', 'We fixed an annoying FOV slider disconnect in our settings menu and implemented realistic air physics to give jumping a sense of weight and commitment.', 'Too Add', '<strong>Syncing the Lens (FOV Slider Fix)</strong><br><br>We noticed a small but incredibly annoying disconnect in our settings menu. When the game started, the FOV slider would default to its minimum value, but the actual camera was set to a much wider perspective. This meant the moment a player touched the slider, the camera would ''snap'' to a different zoom level, making it impossible to find that original sweet spot.<br><br>The Culprit: By default, Unity sliders love to sit at their minimum value on start, regardless of what the actual camera component is doing.<br><br><strong>The Fix:</strong> We added a Start() function to the UI script that polls the camera''s current Field of View and forces the slider handle to match that exact position the moment the game boots. Now, what you see on the menu is exactly what you get on the screen.<br><br><strong>Realistic Air Physics</strong> 📐e = ∑∞ⁿ⁼⁰ ¹ₙ🤓<br><br>We’ve officially moved away from ''perfect'' mid-air control. Previously, you could pivot and accelerate in the sky just as easily as on the ground, which felt a bit too ''floaty'' and arcade-like for the vibe we’re going for.<br><br><strong>''Friction'' Logic:</strong> We introduced a dynamic Friction variable. When the grounded check returns true, friction stays at its normal baseline. However, the moment we leave the floor, that friction value increases.<br><br><strong>The Math:</strong> We now divide our acceleration increment by this friction variable. Because the divisor is higher while in the air, the player ramps up their speed much slower. This gives jumping a sense of weight and commitment, once you’ve launched, you can''t just effortlessly change your mind mid-flight.<br><br><strong>Status Update:</strong><br><br>The movement system is starting to feel less like a collection of scripts and more like a physical body. The air resistance makes every jump feel like a deliberate choice rather than a zero-G glide.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExaDhveTV3MzRqdXJnaDhoNDAwZXo0MDl4NjU1ZmpybG4ydm9haHp2dyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/eNXh84Wk6QIeX2pzMG/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (14, '20260319', 'March 19, 2026 - Robson', 'Devlog: Watch Your Step (The Stair Struggle) 🪜', 'Too Add', 'We’ve implemented a Player Stepping system so we can finally glide over small bumps and ledges, but ran into a ''Super-Jump'' glitch and diagonal blind spots.', 'Too Add', '<strong>Overcoming the Small Stuff (Player Stepping)</strong><br><br>There’s nothing that kills ''brain power'' faster than a powerful protagonist getting stuck on a pebble. We’ve implemented a Player Stepping system so we can finally glide over small bumps and ledges without having to jump every five seconds.<br><br><strong>The Logic:</strong> We’re using a dual-raycast setup. The first ray sits at the very bottom of the collider; if it hits an obstacle, a second ray fires from a slightly higher ''step height.'' If the top ray finds clear air, the code knows it’s a step and not a wall.<br><br><strong>The Lift:</strong> We move the player up incrementally each frame until the bottom ray clears the ledge. We also have to temporarily kill gravity during this ascent, otherwise, the engine tries to pull us back down mid-step, leading to a jittery mess.<br><br><strong>The ''Super-Jump'' Glitch (Unresolved)</strong> 🐇<br><br>We’ve run into a weird interaction we’re calling the Addition Hop. If we time a jump perfectly right as we’re stepping up an object, the player launches into the stratosphere, way higher than a normal jump should go.<br><br><strong>Math Clash:</strong> Both the stepping logic and the jump velocity are trying to add height at the same time. Since they stack, we’re getting double the upward force.<br><br><strong>The Struggle:</strong> We tried forcing the rays to only fire when grounded is true, but the hop still happens. We also tried increasing the step height, but that just caused a fresh war with the gravity toggle. We’ve reverted those tweaks for now to keep the base movement stable while we rethink the logic.<br><br><strong>Diagonal Blind Spots (Semi-Resolved)</strong> 📐<br><br>We hit a bizarre bug where, during diagonal movement, our rays would visually pass through a collider (verified by Debug.DrawRay) but the code would return a ''null'' hit.<br><br><strong>The Mystery:</strong> 🤔We aren''t entirely sure why Unity is being picky about these specific angles, but we suspect it’s a precision issue with the diagonal magnitude.<br><br><strong>''Band-Aid'':</strong> 🩹 We’ve slightly extended the ray distance. It’s a bit of a ''dirty'' fix because it might catch objects we aren''t actually touching yet, but it keeps the movement fluid for now. We’ll need a more elegant solution down the road to avoid ''ghost stepping.''<br><br><strong>Status Report:</strong><br><br>Walking feels much more natural, but our physics interactions are getting complicated. Balancing ''smart'' stepping with manual jumping is proving to be a bit of a tightrope walk.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExdzZqMHBnbW1hNXJlM2ZzdWhnOTBwdmRwYmY5anVpcnk5NmQ5cHUwZyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/3oz8xtd06ZcBwP4yFW/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (15, '20260320', 'March 20, 2026 - Robson', 'Devlog: The Uphill Battle (Slope Struggles) 🏔️📉', 'Too Add', 'We’ve hit a bit of a literal wall with our movement physics today. While we’re great at navigating flat ground and stepping over small bumps, Slopes are currently our greatest enemy.', 'Too Add', 'Fighting the Incline (Unresolved)<br><br>We’ve hit a bit of a literal wall with our movement physics today. While we’re great at navigating flat ground and stepping over small bumps, Slopes are currently our greatest enemy.<br><br><strong>The Problem:</strong> When we try to head up an incline, the player often just... refuses to move, like we''re trying to walk up a slide covered in oil. Even worse, if we manage to get halfway up and let go of the keys, the player doesn''t stay put, they slowly and sadly drift back down to the bottom.<br><br><strong>The Investigation:</strong> We suspect our new acceleration logic might be fighting against the upward force needed to overcome the slope''s angle. As for the sliding, it’s a classic gravity vs. friction showdown where gravity is currently winning. Since we optimized our physics materials to be ''slippy'' for the box collider earlier, we’ve accidentally made ourselves too smooth to hold a position on a ramp.<br><br><strong>Current Status:</strong><br><br>This one is firmly in the ''Work in Progress'' category. We need to find a way to detect when we''re on an incline and perhaps apply a bit of ''extra juice'' to the movement or ''stickiness'' to the feet when we stop. We''re not letting a few degrees of tilt stop our progress.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExZTc1enA4cmd5OWdzNGo3NjM2ZHkwN25uOTVucG1vMzZ5Y2lvOWhvdiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/oJLt6EBsM3WL4LvHms/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (16, '20260324', 'March 24, 2026 - Robson', 'Devlog: Optical Illusions and Vector Hygiene 🔍📐', 'Too Add', 'We finally tracked down why our diagonal rays were acting like they’d seen a ghost, cleaned up our vectors, and realized we were victims of a perspective trick.', 'Too Add', 'The ''Ghost'' Collision (Resolved) 💪🏻💥<br><br>We finally tracked down why our diagonal rays were acting like they’d seen a ghost. We’d be moving at an angle, Debug.DrawRay would show a clear hit into a test cube, but the code would insist there was nothing there. It was driving us toward a total ''brain power'' burnout.<br><br><strong>The Investigation:</strong> Initially, we went on a hunt for un-normalized vectors. We found that the direction vector for our debug line was indeed un-normalized, making it appear longer than the actual physical raycast. We cleaned that up and applied the same logic to all our movement rays, not because it fixed the bug, but because clean code is just good ''radical humanity'' practice.<br><br><strong>The ''Duh'' Moment:</strong> “(ノ _ <,, )<br><br>It turns out we were victims of a perspective trick. The test cube wasn''t actually flush with the floor; it was floating by a hair’s breadth. From our camera angle, it looked like the ray was piercing the cube, but it was actually stopping just short of the gap.<br><br><strong>The Fix:</strong> We’ve officially extended the raycast distance. This time, we aren’t just doing it as a ''band-aid'', we understand the spatial buffer needed to bridge those tiny environmental gaps.<br><br><strong>In the Works:</strong><br><br>We’re still deep in the lab working on the Slope Movement Fix. We’re determined to make inclines feel like a natural part of the world rather than a physics-breaking obstacle.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExczhvczJpdG1zaW1mb2gzOXdoenRkdDB0NHZvNTNvMzg3azFnOGVkciZlcD12MV9naWZzX3NlYXJjaCZjdD1n/LcSmdna8IwSPr6ITbc/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (17, '20260407', 'April 07, 2026 - Robson', 'Devlog: Conquering the Incline (Mostly🤏) 🏔️🧗', 'Too Add', 'We finally broke the stalemate with slopes! For a while, trying to walk up a ramp felt like trying to push a brick wall....the player just stood there...', 'Too Add', '<strong>Victory: The Upward Climb (Resolved)</strong> ✌️😁<br><br>We finally broke the stalemate with slopes! For a while, trying to walk up a ramp felt like trying to push a brick wall, the player just stood there, burning brain power and getting nowhere.<br><br><strong>The Culprit:</strong> It looks like we were accidentally fighting against physics. We were applying our movement force straight forward, essentially trying to walk into the slope rather than along it. The engine was treating every incline like a vertical barrier.<br><br><strong>The Solution:</strong> A massive shoutout to Tim and Logan for the assist here. We started using raycastHit.normal to figure out exactly which way the ground was facing. By using some Vector3.Cross wizardry, we were able to calculate a new movement vector that perfectly hugs the angle of the surface. We aren''t running into the hill anymore; we''re gliding right up it.<br><br><strong>''Pogo-Stick'' Slope (Unresolved)</strong> 📉<br><br>We’ve traded one headache for another. Now that we can move up slopes, the player has decided they can''t stay still. If we stop mid-incline, the protagonist starts bouncing up and down like they’re on a trampoline, even without any input from us.<br><br><strong>The Theory:</strong> To make the upward movement smooth, our targetY is constantly trying to find a coordinate to move toward. Even when we''re stationary, the script is over-correcting, leading to this jittery ''bounce.''<br><br><strong>The Struggle:</strong> We looked into disabling the Y-calculation at certain angles, but the logic quickly spiraled into an endless mess of ''if'' statements that would have prioritized the X-axis and broken the movement anyway. We’re officially calling for backup on this one, we need a cleaner way to tell the player to just stay put.<br><br><strong>Axis of Confusion (Unresolved)</strong> 🧭<br><br>We discovered that our slope-detection math is a bit of a ''one-trick pony.'' If the slope is rotated on the X-axis, it works beautifully. The moment we rotate a ramp on any other axis, the angle returned by our code becomes a total work of fiction.<br><br><strong>Status:</strong> We simply ran out of time to dig into the trigonometry today. It’s likely an issue with how we’re calculating the local vs. world space normals, but for now, we''re just going to have to avoid ''sideways'' hills.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPWVjZjA1ZTQ3cWhvem9zbzgwcDZ4ejc0YTE1eG9tb2wyYnFtOTUzeGluMTJremVvZyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/lnlAifQdenMxW/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (18, '20260408', 'April 08, 2026 - Robson', 'Devlog: The Layer Paradox & Accidental Genius', 'Too Add', 'We solved the haunted rotation bug (it was just a missing layer!), introduced a new notes section for our devlogs, and accidentally cured the pogo-stick slope issue.', 'Too Add', '<strong>Haunted Rotation (Resolved)</strong><br><br>We spent way too much time staring at two identical slopes, losing our minds. On the ''old'' slope, the player bounced like they were on a trampoline. On the ''new'' slope, which was literally just a copy rotated 90 degrees, the movement was perfectly smooth. We checked the surface normals, the math, the physics... everything looked identical.<br><br><strong>Facepalm Moment:</strong> It wasn''t a physics glitch. It wasn''t a rotation error. We simply forgot to set the new slope''s layer to ''Ground.'' Because the script didn''t recognize it as floor, it wasn''t triggering the same heavy-handed Y-axis overrides.<br><br><strong>The Fix:</strong> One click to change the layer, and the ''ghost'' behavior vanished.<br><br><strong>📢Introducing: The ''Don''t Forget'' Buffer (Notes Addition)</strong>📢<br><br>To prevent ourselves from ever wasting hours on a missing layer toggle again, we’ve officially added a Notes Section to our devlogs.<br><br><strong>The Goal:</strong> It’s a dedicated space for us to jot down half-formed thoughts, warnings, or reminders. Whether it''s for the whole team or a note to our future selves, it''s there to protect our collective brain power from repetitive mistakes.<br><br><strong>The Accidental Pogo-Stick Cure (Resolved)</strong><br><br>The bouncing-in-place bug on slopes is finally dead, and honestly? We fixed it by accident while being completely exhausted.<br><br><strong>The Struggle:</strong> We were trying to refactor how we rotated the surface normal using Quaternion.AngleAxis to keep our movement restricted to eight clean directions. We were so tired we could barely see the screen.<br><br><strong>The ''Mistake'' that Worked:</strong> 🤫 We swapped the Vector3.Cross function to use the player’s moveDirection instead of a static axis.<br><br><strong>Science:</strong> When the player stands still, moveDirection becomes (0, 0, 0). You can''t mathematically rotate a vector around a zero-length axis, so the upward force simply ceases to exist when there’s no input. No force, no bounce. We''re calling that a win for ''tired-dev'' logic.<br><br><strong>In the Works:</strong> (Weirdly Angled Slopes🙃)<br><br>We’re tackling slopes that look like they were designed by a cubist, think 50 degrees on Z, 20 on Y, and 10 on X.<br><br><strong>Progress:</strong> By redoing the normal-vector rotation, we’ve successfully constrained the player to 8-directional movement while on a slope. It sounds limiting, but it has actually made these bizarrely angled surfaces navigable for the first time. We''re no longer getting ''dead zones'' where movement just stops for no reason.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPWVjZjA1ZTQ3eGxzYW15cjlxcHM1cWg4aDh1cmpjcDNheG9sN2x0Nmlobmx2dnlidyZlcD12MV9naWZzX3NlYXJjaCZjdD1n/GykSBG6LCsdc8JW1jT/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (19, '20260414', 'April 14, 2026 - Robson', 'Devlog: ''1 Does Not Equal 1'' 🧗‍♂️📉', 'Too Add', 'We overhauled our ground-check with an OverlapBox, grounded our accidental ''Jump-Flight'' bug, and survived an existential crisis where 1 did not equal 1 at the bottom of slopes.', 'Too Add', '<strong>Ground-Check Overhaul</strong><br><br>We realized our protagonist was having a rough time on the edges of platforms. They’d get stuck in a ''no-man''s-land'' where they couldn''t jump or move because the ground check was failing to register the floor.<br><br><strong>The Culprit:</strong> Our previous CheckSphere was simply too small and reached the limits of its detection too early.<br><br><strong>The Fix:</strong> We’ve ditched spheres for a more reliable OverlapBox. By using a box instead of a capsule, we avoid the ''spherical bulge'' that triggers false positives. We centered it precisely on the player’s feet and shaved a tiny bit off the edges so it doesn''t accidentally count walls as ''ground.'' Now, if the OverlapBox returns anything in the list, we’re grounded; if it’s empty, we’re in the air. Simple.<br><br><strong>Ending the ''Jump-Flight'' Program</strong> 🛫<br><br>We hit a bizarre bug where high acceleration allowed the player to stay suspended in the air indefinitely just by holding the jump button.<br><br><strong>The Culprit:</strong> Our targetY variable (designed to help us glide up slopes) was being a bit too aggressive. It was overwriting natural gravity with a tiny, mystery Y-value just above zero. We spent an hour hunting for where that number came from, we still have no idea, but we found a workaround.<br><br><strong>The Fix:</strong> We wrapped the Y-velocity code in a check: if we aren''t explicitly on a slope, we tell the script to back off and let gravity do its job. Flight cancelled.<br><br><strong>''Uphill-Downhill'' Bounce (Unresolved)</strong> 🎢<br><br>Going down slopes currently looks... ridiculous. Instead of a smooth descent, the player hops: up, forward, down, repeat.<br><br><strong>The Theory:</strong> We’re using the ''Up-Slope'' vector for ''Down-Slope'' movement. The player tries to move up into the air, loses contact with the ground, gravity slams them back down, and the cycle starts over.<br><br><strong>The Plan:</strong> We need a way to detect a downward incline specifically. We’re thinking of multiplying the ''Up'' vector by -1, but we need to ensure the detection doesn''t accidentally trigger when we just want to walk sideways. We''re still brainstorming the math on this one.<br><br><strong>The Great Battle of Slope Bottoms (Resolved)</strong> 🛡️<br><br>This was the highlight (or lowlight) of the day. The player was getting stuck exactly where the flat ground met the slope.<br><br><strong>The Logic Crisis:</strong> At one point, we were staring at the console in disbelief because Unity claimed that a Normal''s Y-value of 1 did not equal 1. After nearly three hours of questioning our sanity and theories about ''special floats,'' we realized we were fighting an invisible war with overlapping colliders.<br><br><strong>Breakthrough:</strong> Our raycast was starting inside the ground collider. Since standard Raycasts don''t detect the object they start in, it was ''seeing through'' the floor and hitting a rotated cube buried underneath.<br><br><strong>The Final Fix:</strong> We moved the raycast origin point up by parenting a new slopeRaycastOrigin object to the player. By casting from a few inches higher, the ray correctly hits the floor we''re standing on. We can finally walk onto slopes without having to jump like a clumsy knight! (There’s a tiny ''micro-bounce'' when entering a slope now, but we’ll take that over being stuck any day).<br><br><strong>Current Status:</strong><br><br>We’ve survived the existential crisis of 1 vs 1. The movement is smarter, the ground checks are boxier, and we’re slowly mastering the art of the incline.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPWVjZjA1ZTQ3bGN2ajlnMXhxcGZ3MGQ3a2EycmlrdmgxZTI3amdkZDV0aXAwY3hqZiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/KyALYmovBRV35EQjKE/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (20, '20260415', 'April 15, 2026 - Robson', 'Devlog: Friction Ghost and String Wizardry ⛸️🧵', 'Too Add', 'We exorcised a friction gremlin that felt like walking through molasses, solved the 99.9% edge-case problem, and used string wizardry to fix the great 1 ≠ 1 mystery.', 'Too Add', '<strong>Exorcising the Friction Gremlin</strong> 🚫👹<br><br>We finally tracked down why our movement felt like we were walking through molasses. Even with our acceleration values cranked up, the protagonist was moving at a snail''s pace whenever we weren''t firmly planted on the floor.<br><br><strong>The Culprit:</strong> It turns out we were fighting a ''Negative Force'' ghost. The player was using the default Unity physics material, which comes with standard friction. This was exerting just enough drag to prevent us from gaining momentum unless the grounded check was active. Essentially, the second we lacked ''grounding,'' physics decided we shouldn''t be allowed to move.<br><br><strong>The Fix:</strong> We swapped the default material for our custom Slip Physics Material (zero static and dynamic friction). Now, the player moves with the intended snappiness, regardless of whether their feet are touching a collider or not.<br><br><strong>''99.9%'' Problem</strong><br><br>We solved a rare, hair-pulling bug where the player would occasionally get paralyzed on the extreme edge of an object.<br><br><strong>The Cause:</strong> Our ground-checking box is ever-so-slightly smaller than the player collider (about 99.9% the width) to prevent us from sticking to walls. In extremely rare alignment cases, the player’s collider would be touching the floor, but the ground-check box would be hovering over the abyss by a fraction of a millimeter. Since the engine thought we weren''t grounded, that default friction we mentioned above would lock us in place.<br><br><strong>The Solution:</strong> Using the Slip Physics Material fixed this too! Now, even if the ground-check doesn''t technically register, the lack of friction allows the player to simply walk off the ledge instead of being ''welded'' to it. You still can''t jump from that tiny edge-case, but honestly? Trying to leap from a position where your heels are hanging over a void is pretty hard in real life, too.<br><br><strong>The Great ''1 ≠ 1'' Mystery (Semi-Resolved)</strong> 😵‍💫<br><br>We encountered what we can only describe as a digital existential crisis. We were comparing slopeHit.normal.y to the number 1 at a specific intersection on the map. The console clearly stated both values were 1, yet the code insisted they were False (not equal).<br><br><strong>The Theory:</strong> Floating-point math is a nightmare. Diego suggested this might be a classic approximation error, where a number looks like 1 but is actually 1.0000000000002 deep in the machine''s memory. Why this only happened on one specific part of the map and not others remains a total mystery.<br><br><strong>The Semi-Fix:</strong> We’re now converting both values into Strings limited to two decimal places and comparing those instead. It’s a bit of a ''hack,'' but it forces Unity to agree that 1.00 == 1.00. It’s labeled ''Semi-Resolved'' because we still don''t fully understand and like a toostie pop the world may never know, but at least the game works now.<br><br><strong>Status Report:</strong><br><br>The movement suite is finally shedding its ''clunky'' roots to become a beautful butterfuly. By removing friction from the equation, we’ve made the world feel more responsive and less like a series of physics traps.', 'Too Add', '<img src=''https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExamZhMWx3ZjY0ZXp0aGJkMDUwYjgwdWtmYXczdG15Y2cxMjVkazZiNiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/CCbtQEp3m95WDoZFru/giphy.gif'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');
INSERT OR IGNORE INTO devlogs (id, sort_date, display_date, title_en, title_mi, snippet_en, snippet_mi, content_en, content_mi, image) VALUES (21, '20260526', 'May, 25 2026 - Caitlin', 'Test test ', 'Testio', 'nip nip ', 'nipe nipe', 'con con', 'cone cone ', '<img src=''https://images.peopleimages.com/picture/202304/2808396-confused-thinking-and-woman-in-studio-portrait-for-mistake-decision-or-choice-problem-isolated-on-a-png-background.-doubt-idea-and-model-face-and-hand-scratch-head-for-confusion-sign-on-mockup-fit_400_400.jpg'' style=''width: 100%; height: 100%; object-fit: cover; border-radius: 2px;''>');

