-- foxes
INSERT OR IGNORE INTO foxes (id, name_en, name_mi, year, package_en, package_mi, desc_en, desc_mi, bio_en, bio_mi, image) VALUES (1, 'Frosty', 'Frosty', 2026, 'Digital Video & Bio', 'Ataata me te Haurongo Matihiko', '<strong>Update:</strong> Frosty is our first official studio companion! According to his official biography from the Endangered Wolf Center, he is incredibly healthy. We even got a digital video of him successfully hunting and preparing his den for the harsh winter season.', '<strong>Whakahōu:</strong> Ko Frosty tā mātou mōkai tuatahi! E ai ki tana haurongo whai mana, he tino ora ia. Kua tae mai he ataata e whakaatu ana i a ia e hopu kai ana.', 'Frosty is a young Arctic Fox currently residing at the Endangered Wolf Center. His biography reveals he''s one of the most active members of his pack, often seen exploring his habitat and practicing hunting techniques. During winter months, he demonstrates remarkable survival skills by creating elaborate dens and efficiently caching food. The center staff notes he has a particularly curious personality and often investigates new additions to his environment before the other foxes.', 'Ko Frosty he rēpokia ākitiki taiohi e noho ana i te Endangered Wolf Center. Ko tana haurongo e kī ana ko ia tētahi o ngā mema tino hoihoi o tōna rōpū. I te wā o te hōtoke, ka whakaatuhia e ia ōna pūkenga ora nui mā te hanga i ngā rua matawhānui me te penapena kai. Kei te mōhio ngā kaimahi o te pūnaha he tangata pātai tōna.', '');

-- team
INSERT OR IGNORE INTO team (id, name_en, name_mi, role_en, role_mi, bio_en, bio_mi, avatar, sort_order) VALUES (1, 'Robson', 'Robson', 'Lead Developer', 'Kaiwhakawhanake Matua', 'Robson leads the development team and writes most of the devlogs. When not battling Unity physics bugs, he''s probably debugging why 1 doesn''t equal 1 or wondering why the player is bouncing like a pogo stick.', 'Ko Robson te kaihautū i te rōpū whanaketanga. Kāore ia i te pakanga i ngā hapa ahupūngao o Unity, kei te patuiro ia i te take kāore 1 e ōrite ki 1.', '', 0);

